/**
 * A parsed capture with provenance. Mirrors pennywise `ParsedTransaction`:
 * sender + timestamp travel WITH the payment, not in a sidecar inbox line.
 */
data class ParsedTransaction (
    var `payment`: ParsedPayment
    , 
    /**
     * Sender ID, trimmed + uppercased (sender IDs are case-noisy).
     */
    var `sender`: kotlin.String
    , 
    /**
     * Capture timestamp, epoch millis (carrier or device clock).
     */
    var `timestampMs`: kotlin.Long
    , 
    /**
     * Deterministic content key over amount|direction|merchant|ref.
     * FNV-1a64, stable across restarts (unlike SipHash) — safe as a dedupe
     * key. Sender is DELIBERATELY excluded (audit): an SMS sender
     * (`HDFCBK`) and a push package (`com.gpay`) for one payment would
     * otherwise never hash equal, killing the cross-channel gate. Refs are
     * unique per payment, so same-body collisions across senders need an
     * identical ref too — except ref-less duplicates far apart in time,
     * which merge (accepted, documented).
     */
    var `contentHash`: kotlin.ULong
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeParsedTransaction: FfiConverterRustBuffer<ParsedTransaction> {
    override fun read(buf: ByteBuffer): ParsedTransaction {
        return ParsedTransaction(
            FfiConverterTypeParsedPayment.read(buf),
            FfiConverterString.read(buf),
            FfiConverterLong.read(buf),
            FfiConverterULong.read(buf),
        )
    }

    override fun allocationSize(value: ParsedTransaction) = (
            FfiConverterTypeParsedPayment.allocationSize(value.`payment`) +
            FfiConverterString.allocationSize(value.`sender`) +
            FfiConverterLong.allocationSize(value.`timestampMs`) +
            FfiConverterULong.allocationSize(value.`contentHash`)
    )

    override fun write(value: ParsedTransaction, buf: ByteBuffer) {
            FfiConverterTypeParsedPayment.write(value.`payment`, buf)
            FfiConverterString.write(value.`sender`, buf)
            FfiConverterLong.write(value.`timestampMs`, buf)
            FfiConverterULong.write(value.`contentHash`, buf)
    }
}



/**
 * Merchant normalization + rule-based categorization. Rule-based only — no AI.
 * Port of `lib/core/categorizer.dart`.
 *
 * Match is a word-boundary substring on normalized strings, which doubles as
 * the fuzzy match: "Zomato", "ZOMATO-UB", "zomato order" all hit "zomato",
 * but never inside "buzzomatic".
 * Minimal rule row (callers map their storage rows onto this).
 */
