/**
 * Caller applies the storage side-effect (insert row / write ref onto row id).
 */
sealed class CaptureDecision {
    
    object Insert : CaptureDecision()
    
    
    data class Skip(
        /**
         * Write the candidate ref onto the matched row (it had none).
         */
        val `backfillRef`: kotlin.Boolean) : CaptureDecision()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCaptureDecision : FfiConverterRustBuffer<CaptureDecision>{
    override fun read(buf: ByteBuffer): CaptureDecision {
        return when(buf.getInt()) {
            1 -> CaptureDecision.Insert
            2 -> CaptureDecision.Skip(
                FfiConverterBoolean.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: CaptureDecision): ULong = when(value) {
        is CaptureDecision.Insert -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is CaptureDecision.Skip -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterBoolean.allocationSize(value.`backfillRef`)
            )
        }
    }

    override fun write(value: CaptureDecision, buf: ByteBuffer) {
        when(value) {
            is CaptureDecision.Insert -> {
                buf.putInt(1)
                Unit
            }
            is CaptureDecision.Skip -> {
                buf.putInt(2)
                FfiConverterBoolean.write(value.`backfillRef`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






/**
 * @suppress
 */
public object FfiConverterOptionalULong: FfiConverterRustBuffer<kotlin.ULong?> {
    override fun read(buf: ByteBuffer): kotlin.ULong? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterULong.read(buf)
    }

    override fun allocationSize(value: kotlin.ULong?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterULong.allocationSize(value)
        }
    }

    override fun write(value: kotlin.ULong?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterULong.write(value, buf)
        }
    }
}




